import subprocess
import re
import json

def get_help(cmd_args):
    result = subprocess.run(['./executable'] + cmd_args + ['--help'], capture_output=True, text=True)
    return result.stdout

main_help = get_help([])

commands = []
in_commands = False
for line in main_help.splitlines():
    if line.startswith('Commands:'):
        in_commands = True
        continue
    if in_commands:
        if not line.startswith(' '):
            break
        match = re.match(r'^  ([a-z-]+)\s+', line)
        if match and match.group(1) != 'help':
            commands.append(match.group(1))

def parse_help(help_text):
    # Extracts options and arguments
    args = []
    opts = []

    in_args = False
    in_opts = False
    for line in help_text.splitlines():
        if line.startswith('Arguments:'):
            in_args = True
            in_opts = False
            continue
        elif line.startswith('Options:'):
            in_opts = True
            in_args = False
            continue
        elif not line.startswith(' '):
            in_args = False
            in_opts = False

        if in_args:
            m = re.match(r'^  (<[^>]+>|\[[^\]]+\])\.\.\.', line)
            if m:
                args.append(m.group(1) + "...")
                continue
            m = re.match(r'^  (<[^>]+>|\[[^\]]+\])', line)
            if m:
                args.append(m.group(1))
                continue

        if in_opts:
            # -w, --working-directory <working-directory>
            m = re.match(r'^  (-[a-zA-Z]), (--[a-zA-Z0-9-]+)( <[^>]+>)?', line)
            if m:
                opts.append({'short': m.group(1), 'long': m.group(2), 'takes_value': bool(m.group(3))})
                continue
            m = re.match(r'^      (--[a-zA-Z0-9-]+)( <[^>]+>)?', line)
            if m:
                opts.append({'short': None, 'long': m.group(1), 'takes_value': bool(m.group(2))})
                continue
            m = re.match(r'^  (-[a-zA-Z])( <[^>]+>)?', line)
            if m:
                opts.append({'short': m.group(1), 'long': None, 'takes_value': bool(m.group(2))})
                continue

    return args, opts

data = {}
data['helps'] = {}
data['helps'][''] = main_help
args, opts = parse_help(main_help)
data['cmds'] = {'': {'args': args, 'opts': opts, 'subcmds': commands}}

for cmd in commands:
    h = get_help([cmd])
    data['helps'][cmd] = h
    args, opts = parse_help(h)

    # check for sub-subcommands (like env set)
    subcmds = []
    in_commands = False
    for line in h.splitlines():
        if line.startswith('Commands:'):
            in_commands = True
            continue
        if in_commands:
            if not line.startswith(' '):
                break
            m = re.match(r'^  ([a-z-]+)\s+', line)
            if m and m.group(1) != 'help':
                subcmds.append(m.group(1))

    data['cmds'][cmd] = {'args': args, 'opts': opts, 'subcmds': subcmds}

    for subcmd in subcmds:
        sh = get_help([cmd, subcmd])
        data['helps'][f"{cmd} {subcmd}"] = sh
        sargs, sopts = parse_help(sh)
        data['cmds'][f"{cmd} {subcmd}"] = {'args': sargs, 'opts': sopts, 'subcmds': []}

with open('cli_data.json', 'w') as f:
    json.dump(data, f, indent=2)

print("Parsed commands!")
