import subprocess
import re
import json
import gzip
import base64

def get_help(cmd_args):
    result = subprocess.run(['./executable'] + cmd_args + ['--help'], capture_output=True, text=True)
    return result.stdout

def get_subcmds(h):
    subcmds = []
    in_commands = False
    for line in h.splitlines():
        if line.startswith('Commands:'):
            in_commands = True
            continue
        if in_commands:
            if not line.startswith(' '):
                break
            m = re.match(r'^  ([a-z-]+)\s+', line)
            if m and m.group(1) != 'help':
                subcmds.append(m.group(1))
    return subcmds

def parse_help(h):
    args = []
    opts = []

    in_args = False
    in_opts = False
    for line in h.splitlines():
        if line.startswith('Arguments:'):
            in_args = True
            in_opts = False
            continue
        elif line.startswith('Options:'):
            in_opts = True
            in_args = False
            continue
        elif not line.startswith(' '):
            in_args = False
            in_opts = False

        if in_args:
            m = re.match(r'^  (<[^>]+>|\[[^\]]+\])(\.\.\.)?', line)
            if m:
                is_req = not m.group(1).startswith('[')
                name = m.group(1) + (m.group(2) or '')
                args.append({'name': name, 'required': is_req})
                continue

        if in_opts:
            m = re.match(r'^  (?:(-[a-zA-Z]), )?(?:(--[a-zA-Z0-9-]+))?( <[^>]+>)?', line)
            if m and (m.group(1) or m.group(2)):
                opts.append({
                    'short': m.group(1),
                    'long': m.group(2),
                    'takes_value': bool(m.group(3))
                })
    return args, opts

data = {'helps': {}, 'cmds': {}}

def process_cmd(path):
    h = get_help(path)
    key = " ".join(path)
    data['helps'][key] = base64.b64encode(gzip.compress(h.encode())).decode()

    args, opts = parse_help(h)
    subcmds = get_subcmds(h)
    data['cmds'][key] = {
        'args': args,
        'opts': opts,
        'subcmds': subcmds
    }

    for sc in subcmds:
        process_cmd(path + [sc])

process_cmd([])

with open('cli_data_compressed.json', 'w') as f:
    json.dump(data, f)
print("Done!")
